        uint cBalBefore = address(c).balance;
        c.Deposit{value: a}(); if (__ESBMC_reverted()) return;
        c.Deposit{value: b}(); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == balBefore + a + b && address(c).balance == cBalBefore + a + b);
