// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 a, uint256 b) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        b = bound(b, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a > 0 && b > 0);
        vm.assume(address(this).balance >= a + b);
        try c.SetLogFile(address(this)) {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint cBalBefore = address(c).balance;
        try c.Deposit{value: a}() {} catch { return; }
        try c.Deposit{value: b}() {} catch { return; }
        assertTrue(c.balances(address(this)) == balBefore + a + b && address(c).balance == cBalBefore + a + b);
    }

    function testFuzz_run(uint256 a, uint256 b) public {
        _run(a, b);
    }

    receive() external payable {}

    fallback() external payable {}
}
